package com.healthwise.report.service;import com.healthwise.exception.ResourceNotFoundException;import com.healthwise.report.dto.ReportDtos.*;import com.healthwise.report.entity.Report;import com.healthwise.report.repository.ReportRepository;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;
@Service public class ReportService{private final ReportRepository r;public ReportService(ReportRepository x){r=x;}private Response dto(Report e){return new Response(e.getId(),e.getRecommendationId(),e.getReportName(),e.getUploadedAt(),e.getReportType());}public Response save(String u,Create d){Report e=new Report();e.setUserId(u);e.setRecommendationId(d.recommendationId());e.setReportName(d.reportName());e.setReportType(d.reportType());e.setUploadedAt(Instant.now());return dto(r.save(e));}public List<Response> list(String u){return r.findByUserIdOrderByUploadedAtDesc(u).stream().map(this::dto).toList();}public Response get(String u,String id){return dto(r.findById(id).filter(e->e.getUserId().equals(u)).orElseThrow(()->new ResourceNotFoundException("Report not found")));}public void delete(String u,String id){r.delete(r.findById(id).filter(e->e.getUserId().equals(u)).orElseThrow(()->new ResourceNotFoundException("Report not found")));}}
